import sys

# Read grid
with open('/workdir/data/input.txt', 'r') as f:
    grid = [list(line.strip()) for line in f]

# Find all X positions
X_positions = []
for i, row in enumerate(grid):
    for j, cell in enumerate(row):
        if cell == 'X':
            X_positions.append((i, j))

num_X = len(X_positions)
print(f"Number of X cells: {num_X}")

# Build adjacency list: for each cell, which adjacent cells are X
adj = [[] for _ in range(num_X)]
for idx, (i, j) in enumerate(X_positions):
    for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
        ni, nj = i + di, j + dj
        if 0 <= ni < 5 and 0 <= nj < 10 and grid[ni][nj] == 'X':
            for nid, (ni2, nj2) in enumerate(X_positions):
                if ni2 == ni and nj2 == nj:
                    adj[idx].append(nid)
                    break

# Backtracking to find all Hamiltonian paths using bitmask
all_paths = []

def dfs(node, visited, path):
    if len(path) == num_X:
        all_paths.append(path.copy())
        return
    mask = 1 << node
    for neighbor in adj[node]:
        if not (visited & (1 << neighbor)):
            visited |= (1 << neighbor)
            path.append(neighbor)
            dfs(neighbor, visited, path)
            path.pop()
            visited &= ~mask

for start in range(num_X):
    dfs(start, 1 << start, [start])

print(f"Total Hamiltonian paths: {len(all_paths)}")

# Remove reverse duplicates and ensure start != end
unique_paths = set()
for p in all_paths:
    if p[0] == p[-1]:
        continue
    rev = list(reversed(p))
    if tuple(p) < tuple(rev):
        unique_paths.add(tuple(p))
    else:
        unique_paths.add(tuple(rev))

print(f"Unique paths: {len(unique_paths)}")

# Write to file
with open('/workdir/sol.txt', 'w') as f:
    f.write(str(len(unique_paths)))

print(f"Result written to /workdir/sol.txt: {len(unique_paths)}")
